import{_ as n,o as a,c as e,ag as p}from"./chunks/framework.DUTPmUpA.js";const o="/_assets/guI0g-438a0323a4.DvRYUGcF.png",t="/_assets/guI3k-1c84b64257.B6MnRN58.png",l="/_assets/guIUd-4ce0b6f142.D3A8EGlU.png",u="/_assets/guJ7J-00d69a1243.CsRUasSc.png",v=JSON.parse('{"title":"Пользовательские звуки","description":"","frontmatter":{"title":"Пользовательские звуки","author":"Noya","steamId":"76561198046984233","date":"10.03.2015"},"headers":[],"relativePath":"assets/custom-sounds.md","filePath":"assets/custom-sounds.md"}'),r={name:"assets/custom-sounds.md"};function c(i,s,d,m,b,q){return a(),e("div",null,[...s[0]||(s[0]=[p('<p>вательские звуки</p><p>Вот пошаговое руководство по настройке звуковых событий.</p><h2 id="шаг-1-подготовка-фаила" tabindex="-1">Шаг 1. Подготовка файла <a class="header-anchor" href="#шаг-1-подготовка-фаила" aria-label="Permalink to &quot;Шаг 1. Подготовка файла&quot;">​</a></h2><p>Вам нужен файл с расширением <code>.mp3</code>, <code>.wav</code> может подойти, но я не пробовал. Конвертировать звуки в <code>.mp3</code> можно любым приличным звуковым редактором, я использую Audacity, скачать можно с <a href="https://audacity.sourceforge.net/download/" target="_blank" rel="noreferrer">here</a>.</p><p>Если вам нужен звук из видео на YouTube, я рекомендую использовать этот сайт: <a href="https://www.vidtomp3.com/" target="_blank" rel="noreferrer">https://www.vidtomp3.com/</a></p><h2 id="шаг-2-скопируите-переместите-фаил-в-папку-с-содержимым" tabindex="-1">Шаг 2. Скопируйте/переместите файл в папку с содержимым. <a class="header-anchor" href="#шаг-2-скопируите-переместите-фаил-в-папку-с-содержимым" aria-label="Permalink to &quot;Шаг 2. Скопируйте/переместите файл в папку с содержимым.&quot;">​</a></h2><p>Звуковые файлы, которые будут скомпилированы с помощью Source2 dota, должны быть помещены в папку <strong>content\\dota_addons\\ADDON_NAME\\sounds</strong>. Если у вас его нет, создайте его.</p><p>Структура папок:</p><p><img src="'+o+'" alt="img"></p><h2 id="шаг-3-событие-valve-custom-sounds" tabindex="-1">Шаг 3. Событие Valve Custom Sounds <a class="header-anchor" href="#шаг-3-событие-valve-custom-sounds" aria-label="Permalink to &quot;Шаг 3. Событие Valve Custom Sounds&quot;">​</a></h2><p>Также внутри папки содержимого вашего аддона должна быть папка soundevents:</p><p><img src="'+t+`" alt="img"> Создайте его, если его нет. Здесь расположены текстовые файлы с расширением <strong><code>.vsndevts</code></strong>. Вы можете назвать его как хотите, пока сохраняете это расширение. Я обычно использую <code>custom_sounds.vsndevts</code> для всех звуков аддона и <strong>обязательно предварительно кеширую этот файл где-нибудь</strong> (обычно проще сделать это один раз в Lua Precache(context) и забыть об этом).</p><p>Структура файла довольно проста: это список KV с именем звуковой строки в качестве первого значения каждого звукового блока, а затем множество значений, управляющих различными свойствами звуков, которые в большинстве случаев не так важны, если вы используете этот код:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;SoundStringName&quot;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    &quot;operator_stacks&quot;</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;update_stack&quot;</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;reference_operator&quot;</span></span>
<span class="line"><span>            {</span></span>
<span class="line"><span>                &quot;operator&quot;              &quot;sos_reference_stack&quot;</span></span>
<span class="line"><span>                &quot;reference_stack&quot;       &quot;dota_src1_3d&quot;</span></span>
<span class="line"><span>                &quot;operator_variables&quot;</span></span>
<span class="line"><span>                {</span></span>
<span class="line"><span>                    &quot;vsnd_files&quot;</span></span>
<span class="line"><span>                    {</span></span>
<span class="line"><span>                        &quot;value&quot;</span></span>
<span class="line"><span>                        {</span></span>
<span class="line"><span>                              &quot;value0&quot;        &quot;sounds/FileName.vsnd&quot;</span></span>
<span class="line"><span>                        }</span></span>
<span class="line"><span>                    }</span></span>
<span class="line"><span>                    &quot;volume&quot;            {   &quot;value&quot;     &quot;10.00000&quot;  }</span></span>
<span class="line"><span>                    &quot;pitch_rand_min&quot;    {   &quot;value&quot;     &quot;-0.05000&quot;  }</span></span>
<span class="line"><span>                    &quot;pitch_rand_max&quot;    {   &quot;value&quot;     &quot;0.050000&quot;  }</span></span>
<span class="line"><span>                    &quot;pitch&quot;             {   &quot;value&quot;     &quot;1.000000&quot;  }</span></span>
<span class="line"><span>                    &quot;soundlevel&quot;        {   &quot;value&quot;     &quot;100.00000&quot; }</span></span>
<span class="line"><span>                    &quot;distance_max&quot;      {   &quot;value&quot;     &quot;1600.000&quot;  }</span></span>
<span class="line"><span>                    &quot;event_type&quot;        {   &quot;value&quot;     &quot;1.000000&quot;  }</span></span>
<span class="line"><span>                }</span></span>
<span class="line"><span>            }</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br></div></div><p>Сначала <strong><code>&quot;AddonName.FileName&quot;</code></strong> — желаемая звуковая строка, которая будет использоваться для ее запуска/излучения.</p><p>И последнее и самое важное: <strong><code>&quot;sounds/FileName.vsnd&quot;</code></strong> содержит относительный путь к звуковым файлам, <strong>скомпилированным ValveSound</strong>. Звук, который вы добавили на шаге 2, был <code>.mp3</code>, движок преобразует этот звук в <code>.vsnd</code> при компиляции/сборке файла <strong><code>.vsndevts</code></strong>.</p><p>Во всем блоке это единственные строки, которые вы хотите изменить при добавлении нового звука. По сути, это большая копипаста одного и того же блока, просто меняя эти две строки.</p><p>Конечно, вы можете изменить громкость/высоту своих звуков, поиграйте для этого с переменными оператора.</p><h2 id="шаг-4-выпускаем-и-проверяем-компиляцию-звука" tabindex="-1">Шаг 4. Выпускаем и проверяем компиляцию звука <a class="header-anchor" href="#шаг-4-выпускаем-и-проверяем-компиляцию-звука" aria-label="Permalink to &quot;Шаг 4. Выпускаем и проверяем компиляцию звука&quot;">​</a></h2><p>Как только файл звуковых событий будет готов, вам нужно заставить игру скомпилировать его, прежде чем вызывать строку с помощью KV <code>&quot;FireSound&quot;</code> или любого варианта Lua <code>EmitSound()</code>.</p><p>Для этого зайдите в браузер ресурсов Workshop Tools вашего дополнения, введите имя вашего пользовательского звукового события и выполните полную перекомпиляцию + перезагрузку.</p><p><img src="`+l+'" alt="img"></p><p>Теперь, если вы зайдете в папку дополнений к игре, там должна быть папка звуков и звуковых событий, которая должна содержать скомпилированную <code>_c</code> версию файлов, созданных в папке содержимого.</p><p><img src="'+u+'" alt="img"></p><p>Если это не так, снова зайдите в браузер ресурсов и вместо звукового события введите имя вашего звукового файла и щелкните его. Если он начнет воспроизводиться, значит, он скомпилирован правильно.</p>',25)])])}const g=n(r,[["render",c]]);export{v as __pageData,g as default};
